import sys

def convert_encoding(src, dst):
    try:
        with open(src, 'r', encoding='utf-8') as f:
            text = f.read()
        with open(dst, 'w', encoding='shift_jis') as f:
            f.write(text)
        print("Success")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    convert_encoding('input.txt', 'output.txt')

