import os

def clean_path(input_path):
    if not input_path:
        return "."
    # Replace backslashes with forward slashes for consistency
    processed = input_path.replace("\\", "/")
    # Use normpath to resolve '..' and '.'
    result = os.path.normpath(processed)
    return result

def test():
    test_cases = ["/a/b/../c", "/a//b/c/", "C:\\Users\\temp"]
    for p in test_cases:
        print(f"{p} -> {clean_path(p)}")

if __name__ == "__main__":
    test()

