import json
import os

def load_config(filepath):
    if not os.path.exists(filepath):
        return {"status": "error", "message": "File not found"}
    with open(filepath, 'r') as f:
        return json.load(f)

if __name__ == "__main__":
    config = load_config("settings.json")
    print(config)

